<script setup lang="ts">import{Head,router}from'@inertiajs/vue3';import{reactive}from'vue';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';const p=defineProps<{placements:any[],filters:any}>();const f=reactive({...p.filters});</script><template><Head title="Advertising Inventory"/><div class="space-y-6 p-6"><PageHeader title="Advertising Inventory" description="Review reserved capacity and future availability by placement."/><form @submit.prevent="router.get('/admin/ad-inventory',f)" class="flex gap-3 rounded-xl border p-4"><input v-model="f.from" type="date" class="rounded-md border p-2"/><input v-model="f.to" type="date" class="rounded-md border p-2"/><Button>Check Availability</Button></form><div class="grid gap-4 md:grid-cols-2"><section v-for="pl in placements" :key="pl.id" class="rounded-xl border p-5"><div class="flex justify-between"><h2 class="font-semibold">{{pl.name}}</h2><span>{{pl.available}} of {{pl.capacity}} available</span></div><div v-for="r in pl.reservations" :key="r.id" class="mt-3 rounded-lg bg-muted p-3 text-sm"><strong>{{r.campaign?.name??r.proposal?.title??'Inventory hold'}}</strong><div>{{r.starts_on}} – {{r.ends_on}} · {{r.status}}</div></div></section></div></div></template>